package net.sf.marineapi.ais.parser;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

import net.sf.marineapi.ais.message.AISMessage;
import net.sf.marineapi.ais.util.Sixbit;
import net.sf.marineapi.nmea.sentence.AISSentence;
import org.junit.Before;
import org.junit.Test;

public class AISMessageFactory_create_0_0_Test {

    private AISMessageFactory factory;
    private Map<Integer, Class<? extends AISMessage>> parsers;

    @Before
    public void setUp() throws Exception {
        factory = AISMessageFactory.getInstance();

        // Use reflection to access the private 'parsers' field
        Field parsersField = AISMessageFactory.class.getDeclaredField("parsers");
        parsersField.setAccessible(true);
        parsers = new HashMap<>();
        parsersField.set(factory, parsers);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_NoParserForMessageType() {
        AISSentence sentence = mock(AISSentence.class);
        when(sentence.isFragmented()).thenReturn(false);
        when(sentence.getFragmentNumber()).thenReturn(1);
        when(sentence.getPayload()).thenReturn("payload");
        when(sentence.getFillBits()).thenReturn(0);

        factory.create(sentence);
    }

    @Test
    public void testCreate_Success() throws Exception {
        int messageType = 1;

        AISSentence sentence = mock(AISSentence.class);
        when(sentence.isFragmented()).thenReturn(false);
        when(sentence.getFragmentNumber()).thenReturn(1);
        when(sentence.getPayload()).thenReturn("payload");
        when(sentence.getFillBits()).thenReturn(0);

        // Mock AISMessageParser to return a specific message type
        AISMessageParser parser = mock(AISMessageParser.class);
        when(parser.getMessageType()).thenReturn(messageType);
        when(parser.getSixbit()).thenReturn(new Sixbit("payload", 0));

        // Mock AISMessage class
        Class<? extends AISMessage> messageClass = mock(Class.class);
        AISMessage messageInstance = mock(AISMessage.class);
        when(messageClass.getConstructor(Sixbit.class)).thenReturn(messageClass.getConstructor());
        when(messageClass.getConstructor().newInstance()).thenReturn(messageInstance);

        parsers.put(messageType, messageClass);

        AISMessage result = factory.create(sentence);
        assertNotNull(result);
        assertEquals(messageInstance, result);
    }
}
```

